const cameraplus$4 = { "hero": { "title_1": "Erfasse mehr.", "title_2": "Erschaffe", "title_3": "mehr.", "subtitle": "Camera Plus bietet dir leistungsstarke Werkzeuge, beeindruckende Filter und fortschrittliche Steuerungen, um deine Fotografie auf die nächste Stufe zu heben." }, "quick_features": { "f1_title": "Professionelle\nWerkzeuge", "f1_desc": "All-in-One-Bearbeitung", "f2_title": "Beeindruckende\nFilter", "f2_desc": "Einzigartig für jede Stimmung", "f3_title": "Fortschrittliche\nSteuerungen", "f3_desc": "Manuelle Einstellungen", "f4_title": "RAW-\nUnterstützung", "f4_desc": "Fotos in hoher Qualität", "f5_title": "Ultra-HD-\nQualität", "f5_desc": "Jedes Detail erfassen" }, "airsnap": { "remote_viewfinder": "Fernsucher", "title_1": "Wir stellen vor:", "title_2": "AirSnap", "subtitle": "Fernfotografie, magisch gemacht.", "description": "Möchtest du mit auf dem Gruppenfoto sein, ohne einen Timer zu stellen und loszurennen? Mit AirSnap kannst du zwei iOS-Geräte über WLAN oder Bluetooth verbinden. Nutze ein Gerät, um die Kamera des anderen fernzusteuern!", "f1_title": "iPad als Fernsucher verwenden", "f1_desc": "Sieh genau das, was die iPhone-Kamera sieht, auf dem großen Bildschirm deines iPads, bevor du das perfekte Foto machst.", "f2_title": "Sofortige Synchronisierung", "f2_desc": "Aufgenommene Fotos werden sofort und nahtlos sowohl auf dem aufnehmenden als auch auf dem fernbedienten Gerät gespeichert." }, "macro": { "badge": "MAKRO-MODUS", "title": "Sieh die winzige Welt in unglaublichem Detail.", "explore": "Makro entdecken", "features_title": "Leistungsstarke Funktionen", "features_subtitle": "Eine komplette Suite kreativer Werkzeuge, verpackt in einer intuitiven Oberfläche.", "view_all": "Alle Funktionen ansehen", "f1_title": "Makro-Modus", "f1_desc": "Erfasse winzige Details\nmit beeindruckender Klarheit", "f2_title": "Filter", "f2_desc": "Wende schöne Filter an,\num Aufnahmen hervorstechen zu lassen", "f3_title": "HD-Kameramodus", "f3_desc": "Hohe Auflösung für\nscharfe & lebendige Fotos", "f4_title": "Live-Fotos", "f4_desc": "Erfasse Momente in\nBewegung mit Live-Fotos", "f5_title": "Foto & Video", "f5_desc": "Mach Fotos oder nimm\nVideos ganz einfach auf", "f6_title": "Sperrschutz", "f6_desc": "Schütze deine privaten\nFotos & Videos", "f7_title": "Texterfassung", "f7_desc": "Extrahiere sofort Text\naus jedem Bild" }, "enhancement_tools": { "title": "Professionelle Werkzeuge", "subtitle": "Alles, was du brauchst, um wie ein Profi zu gestalten. Verbessere deine Fotografie mit leistungsstarken integrierten Erweiterungen.", "view_all": "Alle Werkzeuge ansehen", "macro_title": "Makro", "macro_desc": "Entdecke die winzige Welt\nin jedem Detail.", "airsnap_title": "AirSnap\n(Fernfotografie)", "airsnap_desc": "Mach perfekte Aufnahmen\naus der Ferne.", "video_title": "Videoaufnahme", "video_desc": "Nimm flüssige Videos\nin hoher Qualität auf." }, "apple_watch": { "badge": "Apple Watch App", "title_1": "Live-Vorschau &", "title_2": "Fernauslöser", "subtitle": "Sieh deine Aufnahme live in der Vorschau und fotografiere fernbedient direkt von deinem Handgelenk aus. Perfekt für Gruppenfotos und ruhige Aufnahmen.", "learn_more": "Mehr erfahren" }, "testimonials": { "title": "Von Fotografen geliebt", "t1": "Camera Plus hat die Art, wie ich fotografiere, komplett verändert. Die fortschrittlichen Werkzeuge sind unglaublich intuitiv und liefern beeindruckende Ergebnisse. Sehr empfehlenswert!", "t2": "Der Makro-Modus und die Filter sind professionell und einfach zu bedienen. Ich liebe die nahtlose Integration mit meiner Apple Watch für Fernaufnahmen!", "t3": "Die beste Kamera-App, die ich je benutzt habe. Hervorragende Qualität, robuste Funktionen, und die Benutzeroberfläche ist einfach wunderschön. Sie ist jetzt meine tägliche App." } };
const about$4 = { "hero": { "title_1": "Freude schaffen.", "title_2": "Wirkung erzielen.", "founded": "Gegründet", "users": "Nutzer weltweit", "products": "Entwickelte Produkte" }, "story": { "title_1": "Mit Leidenschaft aufgebaut.", "title_2": "Von Zielstrebigkeit angetrieben.", "p1": "Global Delight wurde 2007 an der Südwestküste Indiens, in Udupi, gegründet. Mit unserer perfekten Mischung aus Fachleuten haben wir wegweisende, preisgekrönte plattformübergreifende Audio-, Video- und Fotografie-Anwendungen entwickelt.", "p2": "All dies hat Global Delight zur Heimat einiger der kreativsten und innovativsten Apps gemacht, die weltweit von über 30 Millionen Verbrauchern genutzt werden." }, "team": { "badge": "Lerne unser Team kennen", "title": "Die Menschen hinter unserem Erfolg", "subtitle": "Ein leidenschaftliches Team aus Innovatoren, Machern und Problemlösern, das gemeinsam Freude schafft und Wirkung erzielt.", "join_us": "Mach mit", "could_be_you": "Das könntest du sein!", "view_all": "Alle Karrieremöglichkeiten ansehen", "leader1_role": "Gründer", "leader1_desc": "„Groß träumen, Großes erreichen“ ist Rohith Bhats Motto. Er gründete Global Delight und ist verantwortlich dafür, wo das Unternehmen heute steht. Als Liebhaber von Filmen, neuen Technologien und Gadgets reist und erkundet Rohith auch gerne neue Orte.", "leader2_role": "CEO", "leader2_desc": "Ehemaliger Professor, Patentinhaber im Bereich Browsertechnologien, Geigenvirtuose und Programmierer aus Leidenschaft – Ram Acharya ist all das und mehr. Als Chief Technology Officer liefert er wichtige technische Ausrichtung und Anleitung.", "leader3_role": "Direktor", "leader3_desc": "Ein erfahrener Branchenveteran mit Erfahrung in verschiedenen Bereichen der Technik, Fertigung, Softwareentwicklung und Verwaltung. Absolvent des Ingenieurwesens am KREC Surathkal.", "leader4_role": "Senior Vice President - Engineering", "leader4_desc": "Astronomie, Physik, Philosophie, Ontologie und Technologie sind nur einige der Leidenschaften dieses vielseitigen Ingenieurs. Als Ingenieurabsolvent verfügt er über umfangreiche Erfahrung mit Apple-Technologie mit fast 20 Jahren auf dem Mac und über 10 Jahren iOS. Er hat an einem der größten Open-Source-Projekte, dem Netscape Navigator, mitgewirkt. Er bringt diese umfangreiche Erfahrung zusammen mit praktischem Know-how in die technische Entwicklung unserer Produkte ein.", "m1_role": "Systemingenieur", "m1_quote": "Zukünftige Führungskräfte\nfördern", "m2_role": "Principal Architect", "m2_quote": "Die Leidenschaft\nneu entfachen", "m3_role": "Junior Executive -\nVerwaltung", "m3_quote": "Die Kultur\nverbessern", "m4_role": "UI-Designer", "m4_quote": "Die Kluft überbrücken", "m5_role": "Senior Test Lead", "m6_role": "Webentwickler", "m7_role": "Buchhaltungsmitarbeiter", "m8_role": "Software-Ingenieur", "m9_role": "Marketingmanager", "m10_role": "Senior Buchhaltungsmitarbeiter" } };
