const boom$2 = { "hero": { "eyebrow": "Não apenas ouça.", "headline": "Sinta sua música.", "subtitle": "Um equalizador para todo o sistema, impulsionador de volume e motor de som surround 3D — criado para Mac, Windows, iPhone e Android.", "cta_primary": "Baixe o Boom Grátis", "cta_secondary": "Veja como funciona", "now_playing_title": "Midnight Frequencies", "now_playing_subtitle": "Boom Radio · 3D Mix", "scroll": "Rolar" }, "platforms": { "eyebrow": "Uma Família, Todos os Dispositivos", "title": "Feito para a forma como você ouve", "subtitle": "Seja qual for o dispositivo que você usar, há um aplicativo Boom ajustado para fazê-lo soar melhor.", "boom3d_tag": "Mac & Windows", "boom3d_desc": "Som surround 3D para todo o sistema, um equalizador de 31 bandas e um poderoso impulsionador de volume para seu desktop.", "boom2_tag": "Mac", "boom2_desc": "O aprimorador de áudio original para Mac — predefinições reinventadas, um controle remoto elegante e controle preciso.", "boom_mobile_tag": "iOS & Android", "boom_mobile_desc": "O melhor reprodutor de música com o mágico som surround 3D, direto no seu bolso. Grátis para baixar." }, "showcase": { "eyebrow": "Por que o Boom", "title": "Cada recurso, projetado para te emocionar", "f1_tag": "Áudio Imersivo", "f1_title": "Mágico Som Surround 3D", "f1_desc": "Sinta filmes, jogos e músicas ganharem vida com um efeito de som surround virtual que funciona em qualquer fone de ouvido ou caixa de som — sem precisar de equipamento caro.", "f2_tag": "Precisamente Ajustado", "f2_title": "Equalizador de Precisão de 31 Bandas", "f2_desc": "Molde cada frequência exatamente como você gosta com predefinições de EQ de nível estúdio, ou crie a sua do zero e salve para depois.", "f3_tag": "Mais Alto e Mais Claro", "f3_title": "Impulsionador de Volume Inteligente", "f3_desc": "Vá muito além dos 100% sem distorção. O Boom amplifica seu áudio de forma inteligente para que caixas de som fracas de laptop finalmente soem cheias.", "f4_tag": "Controle Total", "f4_title": "Controle de Áudio por Aplicativo", "f4_desc": "Defina perfis independentes de volume e EQ para cada aplicativo — mantenha o Spotify pulsando enquanto o Slack permanece discreto em segundo plano." }, "stats": { "downloads": "Total de downloads", "countries": "Países alcançados", "rating": "Avaliação média", "awards": "Prêmios da crítica" }, "testimonials": { "title": "Amado por milhões", "subtitle": "Avaliações reais da comunidade Boom em todas as plataformas.", "r1_title": "Completamente imersivo.", "r1_text": "O efeito surround 3D faz meus fones de ouvido comuns soarem como um par de 200 dólares. Não consigo voltar atrás.", "r2_title": "Finalmente, alto o suficiente.", "r2_text": "As caixas de som do meu laptop sempre foram muito baixas. O Boom resolveu isso instantaneamente sem nenhuma distorção.", "r3_title": "O melhor EQ que já usei.", "r3_text": "O equalizador de 31 bandas é genuinamente de nível estúdio. Eu o uso diariamente para verificações de referência em mixagem.", "r4_title": "Funciona em qualquer lugar.", "r4_text": "Tenho no meu Mac e no meu celular — o mesmo ótimo som onde quer que eu esteja. Experiência perfeita.", "r5_title": "O controle por aplicativo é genial.", "r5_text": "Manter o Slack quieto enquanto minha música continua forte é uma coisa pequena que faz uma grande diferença.", "r6_title": "Vale cada centavo.", "r6_text": "Um dos poucos aplicativos pelos quais paguei com prazer assim que o teste terminou. Um verdadeiro divisor de águas para o áudio." }, "cta": { "title": "Pronto para sentir sua música?", "subtitle": "O Boom é gratuito para testar em todas as plataformas. Escolha seu dispositivo e comece a ouvir de forma diferente hoje mesmo.", "macos": "macOS", "windows": "Windows", "ios_android": "iOS & Android" } };
const boom2$2 = { "hero": { "title_1": "Seu Áudio,", "title_2": "Reinventado.", "subtitle": "O Boom 2 é o aplicativo definitivo de aprimoramento de áudio que dá vida à sua música, filmes e jogos com ferramentas poderosas e som 3D imersivo.", "download_trial": "BAIXAR TESTE", "buy_now": "COMPRAR AGORA" }, "features_banner": { "eq": "Equalizador\nde 31 Bandas", "effects": "Efeitos\nde Áudio", "system_wide": "Controle de\nTodo o Sistema", "file_boost": "Impulso de\nArquivo", "remote": "Controle\nRemoto Boom", "output": "Compatibilidade\nde Saída", "sample_rate": "Controle de\nTaxa de Amostragem", "balancer": "Balanceador de Áudio\n(E-D)", "stereo": "Ampliação\nEstéreo" }, "precision": { "title": "Aprimoramento de Som Estéreo com Impulso de Volume e Equalizador para macOS", "description": "O Boom 2 é um aplicativo premiado de aprimoramento de áudio profissional para macOS, que oferece um nível extraordinário de controle sobre todo o seu áudio. É uma solução única para fazer tudo soar verdadeiramente perfeito!" }, "feature_grid": { "c1_title_1": "Som", "c1_title_2": "Surround 3D", "c1_desc": "Experimente um áudio 3D imersivo que te coloca no centro da ação.", "c2_title_1": "Efeitos de", "c2_title_2": "Áudio Poderosos", "c2_desc": "Aplique efeitos avançados como Ambience, Fidelity e mais para aprimorar cada detalhe.", "c3_title_1": "Impulsionador", "c3_title_2": "de Volume", "c3_desc": "Aumente o volume do seu sistema além dos limites e aproveite cada som no seu melhor.", "c4_title_1": "Controle de", "c4_title_2": "Todo o Sistema", "c4_desc": "Controle volume, impulso e efeitos em todos os aplicativos e saídas." }, "remote_control": { "remote_title": "Controle Remoto", "remote_desc": "Controle o Boom 2 do seu iPhone com o aplicativo Boom Remote.", "recorder_title": "Gravador de Áudio", "recorder_desc": "Grave qualquer áudio reproduzido no seu Mac em alta qualidade.", "output_title": "Dispositivos de Saída", "output_desc": "Alterne facilmente entre várias saídas de áudio." }, "testimonials": { "title_1": "Amado por", "title_2": "Milhões", "subtitle": "Veja o que nossos usuários têm a dizer sobre a experiência do Boom 2.", "r1_title": "Incrível!", "r1_text": "Isso vai mudar totalmente como o áudio soa no seu Mac. É especialmente perceptível com fones de ouvido. Se você tem fones fracos, este aplicativo os fará soar como um par de 200 dólares.", "r2_title": "Som ótimo.", "r2_text": "Estou ouvindo toda a minha música favorita de novo, como se fosse a primeira vez. Uso monitores de estúdio conectados ao meu Mac e agora finalmente sei do que eles realmente são capazes. Estou muito feliz por ter comprado o Boom.", "r3_title": "Melhor som de todos!", "r3_text": "Este foi um investimento que valeu muito a pena. Meu MacBook Pro com minhas caixas de som externas 5.1 soam incríveis!! Continuem com o ótimo trabalho!", "r4_title": "Aplicativo excelente!", "r4_text": "As caixas de som do meu MacBook Pro 17 estavam muito baixas — mesmo no volume máximo. Instalei o Boom 2 e agora, a menos da metade do volume, elas ficam mais altas do que antes no volume máximo. Este é um APLICATIVO EXCELENTE!", "r5_title": "Realmente funciona..", "r5_text": 'Depois que você configura o Boom 2 e começa a usá-lo com um bom fone de ouvido, não há mais volta. O áudio musical "normal" simplesmente não é mais suficiente. É realmente a melhor forma de deixar a música envolvente e rica.', "r6_title": "Diferença como dia e noite!", "r6_text": "Ouvir música com e sem o aplicativo ligado é uma diferença como dia e noite. Cheguei até a parar de ouvir música no meu PC porque não há nada parecido no Windows. Altamente recomendado!", "r7_title": "Aplicativo indispensável para qualquer Mac.", "r7_text": "O som do Mac muda completamente assim que o Boom é instalado e ativado. Não apenas as caixas de som do Mac, mas também caixas externas 5.1 e fones de ouvido. Indispensável, na minha opinião.", "r8_title": "Melhor do que eu imaginava!", "r8_text": "Eu estava pronto para devolver meu MacBook porque as caixas de som não projetam bem para filmes. Consegui o Boom e UAU. Não faço ideia de como funciona, mas funciona! Um som incrível agora sai do meu MacBook. Sim!", "r9_title": "Torna a música mais agradável..", "r9_text": "Adoro poder ajustar o som do meu MacBook. Ambience é minha configuração favorita. Quase me lembra o antigo SRS WOW dos anos 2000-2010. Quase como uma melhoria mágica do som.", "r10_title": "Eleva sua experiência de audição.", "r10_text": "Poder usar o equalizador para ajustar o som que sai do meu Mac (usando fones de estúdio/com cancelamento de ruído) é incrível. Consigo destacar cada instrumento. Não consigo imaginar ouvir música sem o Boom!", "r11_title": "Vale a pena..", "r11_text": "Adoro este aplicativo. O equalizador é incrível e simplesmente faz tudo soar melhor. Também gosto de poder aumentar o volume para conseguir ouvir mesmo se eu for para outro cômodo enquanto escuto algo." }, "footer_cta": { "title": "Pronto para Elevar seu Áudio?", "subtitle": "Junte-se a milhões de usuários e experimente o som como nunca antes.", "download": "Baixe Agora", "available_macos": "Disponível para macOS" }, "audio_amplify": { "title": "Amplifique arquivos de áudio individualmente", "description": "Aumente permanentemente o volume de qualquer arquivo de áudio no seu Mac, individualmente ou em lote. Seja um memorando de voz baixo, um podcast com volume fraco ou uma música mal gravada, o Boom 2 permite que você arraste facilmente arquivos de áudio e os amplifique até o volume desejado. Você pode amplificar vários arquivos de uma só vez, economizando tempo e garantindo que todas as suas mídias fiquem altas e claras para reprodução em qualquer dispositivo." }, "awards": { "title": "Prêmios e Reconhecimentos", "alt_2011": "Prêmio 2011", "alt_2014": "Prêmio 2014", "alt_2018": "Prêmio 2018", "alt_macworld": "Prêmio Macworld" } };
