const audion$2 = { "hero": { "title_1": "Aprimore suas gravações de áudio com o", "title_2": "AudiOn", "subtitle": "O aplicativo de gravação de voz de ponta projetado para profissionais, estudantes e criadores. Experimente gravação, edição e transcrição com qualidade de estúdio direto no seu bolso." }, "advanced_recording": { "title_1": "Gravação", "title_2": "Avançada", "subtitle": "O AudiOn expande os limites de hardware do seu smartphone, dando a você um controle sem precedentes sobre como você captura o som.", "f1_title": "Gravação de Áudio Sem Perdas", "f1_desc": "Capture cada nuance com formatos de gravação WAV não comprimidos e com qualidade de estúdio, projetados para profissionais.", "f2_title": "Aumento de Sensibilidade do Microfone", "f2_desc": "Amplifique o microfone embutido do seu dispositivo em até 200% para capturar claramente falantes baixos ou sons distantes.", "f3_title": "Personalização em Tempo Real", "f3_desc": "Ajuste o tom e a velocidade de reprodução instantaneamente sem afetar a qualidade da gravação original.", "f4_title": "Teleprompter Integrado", "f4_desc": "Leia seus roteiros perfeitamente durante a gravação. Nosso teleprompter flutuante rola seu texto na velocidade de sua preferência." }, "enhancement": { "title_1": "Aprimoramento de Áudio", "title_2": "Inteligente", "subtitle": "Limpe ambientes barulhentos e refine suas gravações com ferramentas de processamento inteligente de um toque.", "noise_title": "Remoção de Ruído e Isolamento de Voz", "noise_desc": "Remova instantaneamente zumbido de fundo, vento e conversas para tornar sua voz o ponto focal.", "noise_visual": "Isolando Perfil de Voz...", "silence_title": "Pular Silêncio", "silence_desc": "Detecte e pule automaticamente pausas silenciosas para economizar tempo ao revisar gravações longas.", "silence_visual": "Detectando Ar Morto...", "eq_title": "Reverb e EQ Profissional", "eq_desc": "Aplique efeitos de reverberação de ambiente profissional e ajuste frequências usando nosso equalizador de 6 bandas.", "eq_visual": "Aplicando Reverb de Estúdio..." }, "transcription": { "title_1": "Fluxo de Trabalho Poderoso", "title_2": "Pós-Gravação", "subtitle": "O AudiOn oferece um conjunto completo de ferramentas de edição para que você nunca precise exportar para um aplicativo desktop para finalizar seu áudio.", "editing_title": "Edição de Precisão", "editing_desc": "Corte, aparare e mescle clipes de áudio sem esforço. Nosso editor de forma de onda intuitivo permite que você amplie para fazer edições precisas em milissegundos diretamente no seu dispositivo móvel.", "markers_title": "Marcadores de Timestamp", "markers_desc": "Adicione marcadores durante a gravação ou reprodução para voltar instantaneamente a momentos importantes. Perfeito para navegar por longas palestras, entrevistas ou reuniões.", "transcription_title": "Transcrição de Voz para Texto", "transcription_desc": "Converta suas notas de voz em texto instantaneamente. O AudiOn suporta transcrição altamente precisa, facilitando a busca, cópia e compartilhamento de suas ideias faladas." }, "newsletter": { "title_1": "Fique", "title_2": "por dentro", "subtitle": "Assine nossa newsletter para receber as últimas atualizações, dicas de gravação de áudio e ofertas exclusivas do AudiOn.", "email_placeholder": "Digite seu endereço de e-mail", "subscribed": "Inscrito!", "subscribe": "Inscrever-se", "privacy_note": "Ao se inscrever, você concorda com nossa", "privacy_policy": "Política de Privacidade", "privacy_note_end": ". Nunca enviamos spam." } };
