const about = { "hero": { "title_1": "创造愉悦。", "title_2": "带来影响。", "founded": "成立于", "users": "全球用户", "products": "已开发产品" }, "story": { "title_1": "以热情打造。", "title_2": "以使命驱动。", "p1": "Global Delight 于 2007 年在印度西南海岸的乌杜皮成立。凭借专业人才的完美结合，我们打造出了领先的、屡获殊荣的跨平台音频、视频和摄影应用程序。", "p2": "所有这一切，都让 Global Delight 成为全球超过 3000 万消费者所使用的一些最具创意和创新的应用程序的诞生地。" }, "team": { "badge": "认识我们的团队", "title": "成就我们成功的人们", "subtitle": "一支充满热情的创新者、创作者和问题解决者团队，共同努力创造愉悦并带来影响。", "join_us": "加入我们", "could_be_you": "这可能就是您！", "view_all": "查看所有招聘信息", "leader1_role": "创始人", "leader1_desc": '"敢想敢干"是 Rohith Bhat 的座右铭。他创立了 Global Delight，并对其今日的成就负有主要责任。他热爱电影、新兴科技和电子产品，同时也喜爱旅行和探索新地方。', "leader2_role": "首席执行官", "leader2_desc": "前教授、浏览器技术专利持有者、小提琴大师，同时也是一位骨子里的程序员——Ram Acharya 集这一切于一身，甚至更多。作为首席技术官，他为公司提供了极大的技术方向和指导。", "leader3_role": "总监", "leader3_desc": "一位经验丰富的行业资深人士，在工程、制造、软件开发和行政管理等多个领域都有涉猎。毕业于 KREC Surathkal 工程专业。", "leader4_role": "高级工程副总裁", "leader4_desc": "天文学、物理学、哲学、本体论和技术，只是这位善于思考的工程师众多热情所在中的一部分。作为一名工程专业毕业生，他在 Apple 技术方面拥有丰富的经验，在 Mac 平台上工作近 20 年，在 iOS 平台上工作超过 10 年。他曾参与过最大的开源项目之一 Netscape Navigator 的开发。他将这份丰富的经验以及在我们产品工程方面的实战技巧带入团队。", "m1_role": "系统工程师", "m1_quote": "培养未来的\n领导者", "m2_role": "首席架构师", "m2_quote": "重燃\n热情", "m3_role": "初级执行专员 -\n行政部门", "m3_quote": "改善\n企业文化", "m4_role": "UI 设计师", "m4_quote": "弥合差距", "m5_role": "高级测试主管", "m6_role": "网页开发人员", "m7_role": "账务专员", "m8_role": "软件工程师", "m9_role": "市场营销经理", "m10_role": "高级账务专员" } };
